using System;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEngine;
namespace BWVR.Editor {
public static class ConstructionUseChecks {
 [MenuItem("BWVR/Verify villager construction use and requests (Play mode)")]
 public static void Verify(){if(!EditorApplication.isPlaying)throw new Exception("Enter Play mode first");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var god=UnityEngine.Object.FindAnyObjectByType<CreatureHybrid>();var learning=god.GetComponent<CreatureConstructionLearning>();var site=learning.sites[0];var field=typeof(QuestSlice).GetField("state",BindingFlags.Instance|BindingFlags.NonPublic);var original=(SliceState)field.GetValue(slice);god.Interrupt("Construction use QA");var test=new SliceState{water=100,developmentFocus=true};field.SetValue(slice,test);var actors=slice.GetComponentsInChildren<VillagerExploration>();foreach(var a in actors){a.ResetTask();a.GetComponent<VillagerSocial>().ResetTask();a.GetComponent<VillagerBlockPlay>().ResetTask();}var actor=actors[0];var memory=actor.GetComponent<VillagerSocial>().Memory;var nav=actor.GetComponent<IslandNavigator>();var position=actor.transform.position;
  void Stage(){actor.ResetTask();site.Paused=false;site.ResetConstruction();if(!nav.world.Sample(site.World(new Vector3(0,0,-12)),nav.profile,12,out var at))throw new Exception("No construction approach");actor.transform.position=nav.world.ProjectFoot(at,nav.profile);nav.ResetRoute();}
  void Build(BuildRecipe recipe){site.Recipe=recipe;foreach(var p in ConstructionPatterns.Plan(recipe)){var b=site.blocks.First(b=>!b.Attached&&(b.size.x>3)==p.beam);if(!site.Drop(b,site.World(p.position),site.transform.rotation,true))throw new Exception("Recipe fixture did not snap");for(int i=0;i<5;i++)site.Advance(.02f);}if(!site.RecipeComplete)throw new Exception("Incomplete construction fixture");}
  try{Stage();memory.restNeed=.9f;if(!actor.TryBuildingNeed(site))throw new Exception("Villager could not express need");for(int i=0;i<2000&&actor.Current!=VillagerExploration.Phase.ShowNeed;i++)actor.Tick(.05f,false);if(!actor.ShowingBuildingNeed||memory.buildRequests!=1||site.Requester!=actor)throw new Exception("No visible building request");actor.Tick(4,false);var hands=actor.GetComponentInChildren<HumanoidHands>();if(!hands.beckon||!hands.indicating||!learning.BenchRequested)throw new Exception("Missing nonverbal request gestures");god.Perceive();var choices=(System.Collections.Generic.List<CreatureCandidate>)typeof(CreatureHybrid).GetField("candidates",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(god);if(!choices.Any(c=>god.Find(c.target)?.GetComponent<ConstructionInspiration>()?.recipe==BuildRecipe.Bench&&c.affinity>.6f))throw new Exception("Request did not influence observation utility");var example=god.Targets.First(t=>t.GetComponent<ConstructionInspiration>()?.recipe==BuildRecipe.Bench);learning.Observe(example.GetComponent<ConstructionInspiration>());learning.Tick();if(site.Recipe!=BuildRecipe.Bench)throw new Exception("Learned form did not address gathering need");actor.ResetTask();
   foreach(var recipe in new[]{BuildRecipe.Arch,BuildRecipe.Bench,BuildRecipe.Tower}){Stage();Build(recipe);memory.restNeed=.9f;int count=memory.constructionUses;float trust=memory.trust;if(!actor.TryStructure(site)||actors[1].TryStructure(site))throw new Exception("Structure visit reservation failed");var phase=actor.Current;actor.Tick(10,true);if(actor.Current!=phase||memory.constructionUses!=count)throw new Exception("Paused structure use advanced");for(int i=0;i<3000&&memory.constructionUses==count;i++)actor.Tick(.05f,false);if(memory.constructionUses!=count+1||memory.restNeed>=.9f||memory.trust<=trust||site.Visitor!=null)throw new Exception("Native use/reaction failed: "+recipe);}
   actor.ResetTask();float learned=memory.trust;int before=memory.constructionUses;if(!actor.TryStructure(site))throw new Exception("Repeated inspection rejected");for(int i=0;i<3000&&memory.constructionUses==before;i++)actor.Tick(.05f,false);if(memory.trust!=learned)throw new Exception("Repeated same form farmed trust");
   actor.ResetTask();if(!actor.TryStructure(site))throw new Exception("Removal setup failed");int disappointed=memory.buildDisappointments;site.blocks.First(b=>b.Attached).Grab();actor.Tick(.1f,false);if(site.Visitor!=null||memory.buildDisappointments!=disappointed+1)throw new Exception("Removed support did not cancel use/react");
   var saved=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test));if(!saved.Valid()||saved.relationships.All(m=>m.usedForms!=7))throw new Exception("Structure experience did not save");Debug.Log("BWVR_CONSTRUCTION_USE_PASS: nonverbal rest/gather request; observation utility bias; learned form selection without forced motor command; native arch passage, bench gathering and tower inspection; pause; visitor lease; rest benefit; first-form creature credit; no repeated trust farming; dismantling reaction and cleanup; saved memory");
  }finally{actor.ResetTask();site.ResetConstruction();actor.transform.position=position;nav.ResetRoute();field.SetValue(slice,original);god.Interrupt("Construction use QA complete");}
 }
}
}
